@js:
var url=source.key+result;
var web=java.webView(null,url,null),
j=org.jsoup.Jsoup.parse(web);
var page=j.select(".f-cb li").length;
java.put("page",page);
result.replace('/m/',"/api/");

ruleToc.nextTocUrl:
@js:
var page=java.get("page");
var url=[];
if(page){
	for(i=2;i<=page;i++){
		var next=baseUrl.replace(/\d+.$/,i+"/")
		url.push(next);
		}
	}
url;

